/* ===== ALAT BANTU ===== */
const $ = (s) => document.querySelector(s),
  $$ = (s) => [...document.querySelectorAll(s)];
const fmt = (n) => 'Rp ' + Math.round(n).toLocaleString('en-US');

/* ===== 1. Perbandingan singkong vs nasi ===== */
const vs = $('#vs');
function vsUp() {
  const v = +vs.value / 100;
  $('#s1').style.transform = `scale(${1 + v * 0.25}) translateX(${-v * 8}px)`;
  $('#s2').style.transform = `scale(${1 - v * 0.2})`;
  $('#bf1').style.width = 20 + v * 70 + '%';
  $('#bg1').style.width = 85 - v * 40 + '%';
  $('#vsTxt').textContent = v < 0.15 ? 'Slide to compare…' : v < 0.7 ? 'Cassava starts to lead: more fibre, lower GI.' : 'Cassava: higher fibre, lower GI.';
}
vs.oninput = vsUp;
vsUp();

/* ===== 2. Tab Argumen ===== */
function openTab(id) {
  $$('.tab').forEach((t) => t.setAttribute('aria-selected', t.dataset.p === id));
  $$('.panel').forEach((p) => (p.hidden = p.id !== id));
  if (id === 'pa') gi();
  if (id === 'pb') fiber();
}
$$('.tab').forEach((t) => (t.onclick = () => openTab(t.dataset.p)));

/* ===== 3. Gauge IG dan serat ===== */
function count(el, to, d = 0, ms = 800) {
  const t0 = performance.now();
  (function f(t) {
    const k = Math.min(1, (t - t0) / ms);
    el.textContent = (to * k).toFixed(d);
    if (k < 1) requestAnimationFrame(f);
  })(t0);
}
function gi() {
  const p = $('#pin');
  p.style.left = '0%';
  count($('#giN'), 56);
  setTimeout(() => (p.style.left = (56 / 100) * 100 + '%'), 60);
}
$('#giB').onclick = gi;
function fiber() {
  $('#fib').style.width = '0';
  setTimeout(() => ($('#fib').style.width = (4.72 / 8) * 100 + '%'), 60);
  count($('#fibN'), 4.72, 2);
}
$('#por').oninput = (e) => {
  $('#pv').textContent = e.target.value;
  $('#gr').textContent = (e.target.value * 0.0472).toFixed(1);
};

/* ===== 4. Kalkulator ekonomi ===== */
function eco() {
  const m = +$('#mod').value || 0;
  $('#rev').textContent = fmt(m * 1.66);
  $('#pro').textContent = fmt(m * 0.66);
}
$('#mod').oninput = eco;
eco();

/* ===== 5. Menu dan manfaat ===== */
